use std::fmt::Write;
use std::path::Path;

use crabrouter_model::RouterConfig;

use crate::Result;

pub fn render_containers_conf(cfg: &RouterConfig) -> String {
    format!(
        "# Generated by crabrouterd\n\
         [containers]\n\
         cgroup_manager = \"systemd\"\n\
         log_driver = \"journald\"\n\
         cgroups = \"enabled\"\n\n\
         [engine]\n\
         cgroup_manager = \"systemd\"\n\
         events_logger = \"journald\"\n\
         runtime = \"crun\"\n\n\
         [network]\n\
         network_backend = \"netavark\"\n\
         firewall_driver = \"nftables\"\n\
         dns_bind_port = {}\n\
         default_subnet = \"{}\"\n",
        cfg.containers.dns_bind_port, cfg.containers.default_subnet
    )
}

pub fn render_storage_conf(cfg: &RouterConfig) -> String {
    format!(
        "# Generated by crabrouterd\n\
         [storage]\n\
         driver = \"overlay\"\n\
         runroot = \"/run/containers/storage\"\n\
         graphroot = \"{}\"\n",
        cfg.containers.storage_root
    )
}

pub fn render_registries_conf(cfg: &RouterConfig) -> String {
    let mut out = String::from(
        "# Generated by crabrouterd\n\
         unqualified-search-registries = [\"docker.io\", \"ghcr.io\"]\n",
    );
    if !cfg.containers.registry_mirrors.is_empty() {
        out.push_str("\n[[registry]]\nprefix = \"docker.io\"\nlocation = \"docker.io\"\n");
        for mirror in &cfg.containers.registry_mirrors {
            let normalized = normalize_mirror_location(mirror);
            if normalized.is_empty() {
                continue;
            }
            let _ = writeln!(out, "\n[[registry.mirror]]\nlocation = \"{normalized}\"");
        }
    }
    out
}

fn normalize_mirror_location(raw: &str) -> &str {
    let trimmed = raw.trim();
    let without_scheme = trimmed
        .strip_prefix("https://")
        .or_else(|| trimmed.strip_prefix("http://"))
        .unwrap_or(trimmed);
    without_scheme.trim_end_matches('/')
}

pub fn render_containers_slice(cfg: &RouterConfig) -> String {
    let mut out = String::from(
        "# Generated by crabrouterd\n\
         [Unit]\n\
         Description=CrabRouter Container Workload Slice\n\
         Before=slices.target\n\n\
         [Slice]\n\
         MemoryAccounting=yes\n\
         CPUAccounting=yes\n",
    );
    if cfg.containers.memory_max_mb > 0 {
        let _ = writeln!(out, "MemoryMax={}M", cfg.containers.memory_max_mb);
    }
    if cfg.containers.cpu_quota_percent > 0 {
        let _ = writeln!(out, "CPUQuota={}%", cfg.containers.cpu_quota_percent);
    }
    out
}

pub async fn sync_container_host_configs(
    cfg: &RouterConfig,
    containers_dir: &Path,
    systemd_dir: &Path,
) -> Result<()> {
    if !cfg.containers.enabled {
        return Ok(());
    }
    let registries_d = containers_dir.join("registries.conf.d");
    tokio::fs::create_dir_all(&registries_d).await?;
    tokio::fs::create_dir_all(systemd_dir).await?;

    write_atomic(
        &containers_dir.join("containers.conf"),
        &render_containers_conf(cfg),
    )
    .await?;
    write_atomic(
        &containers_dir.join("storage.conf"),
        &render_storage_conf(cfg),
    )
    .await?;
    write_atomic(
        &registries_d.join("99-crabrouter.conf"),
        &render_registries_conf(cfg),
    )
    .await?;
    write_atomic(
        &systemd_dir.join("crabrouter-containers.slice"),
        &render_containers_slice(cfg),
    )
    .await?;
    Ok(())
}

async fn write_atomic(path: &Path, content: &str) -> Result<()> {
    let tmp = path.with_extension("tmp");
    tokio::fs::write(&tmp, content).await?;
    tokio::fs::rename(&tmp, path).await?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use crabrouter_model::RouterConfig;

    use super::*;

    #[test]
    fn renders_containers_storage_registries_and_slice() {
        let mut cfg = RouterConfig::default();
        cfg.containers.enabled = true;
        cfg.containers.dns_bind_port = 5355;
        cfg.containers.memory_max_mb = 2048;
        cfg.containers.cpu_quota_percent = 150;
        cfg.containers.registry_mirrors = vec!["mirror.ccs.tencentyun.com".to_string()];

        let containers_conf = render_containers_conf(&cfg);
        assert!(containers_conf.contains("firewall_driver = \"nftables\""));
        assert!(containers_conf.contains("dns_bind_port = 5355"));
        assert!(containers_conf.contains("default_subnet = \"10.88.0.0/16\""));

        let storage_conf = render_storage_conf(&cfg);
        assert!(storage_conf.contains("driver = \"overlay\""));
        assert!(storage_conf.contains("runroot = \"/run/containers/storage\""));
        assert!(storage_conf.contains("graphroot = \"/var/lib/containers/storage\""));

        let registries_conf = render_registries_conf(&cfg);
        assert!(registries_conf.contains("mirror.ccs.tencentyun.com"));

        cfg.containers.registry_mirrors = vec!["https://docker.1ms.run/".to_string()];
        let normalized_conf = render_registries_conf(&cfg);
        assert!(normalized_conf.contains("location = \"docker.1ms.run\""));
        assert!(!normalized_conf.contains("https://"));

        let slice = render_containers_slice(&cfg);
        assert!(slice.contains("MemoryMax=2048M"));
        assert!(slice.contains("CPUQuota=150%"));
    }
}
